) AS (
  VALUES 
    (532::BIGINT, 'Preparese para escribir un montón. La profe es sería pero no es mala, solo siga instrucciones y sobrevive.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2026-08-06T00:00:00+00:00'::TIMESTAMPTZ, 'da5dd4a978201572f4a110f9ea5f0fdca21d8c71384141a1d8944f7c6d506a70'::TEXT, ARRAY[567]::BIGINT[]),
    (532::BIGINT, 'Me da miedo, pero al final fue bastante amigable, explica al inicio, quizzes fáciles pero específicos, califica suave. Solo tiene q ir al día y ser responsable'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2026-07-04T00:00:00+00:00'::TIMESTAMPTZ, 'e7e1e7e932d0f5d4dc7332aa110e55f7bb33c99393bb714bf035fbd0cab72116'::TEXT, ARRAY[567]::BIGINT[]),
    (532::BIGINT, 'Se pasa fácil, solo haga las cosas que deje hacer y no falte a clases. Es comprensiva, explica bien, es excelente.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2026-07-03T00:00:00+00:00'::TIMESTAMPTZ, '0c2a700eb5d3d2a0c27beb261436c9ed6c5be53a922d96dfdc0a760d90415e8d'::TEXT, ARRAY[567]::BIGINT[]),
    (532::BIGINT, 'Es buena profe, califica justo, las correcciones que hace en los informes ayudan bastante, es muy seria pero es buena gente, se aprende tu nombre algo que pocos profes hacen. Si uno tiene dudas ella ayuda bastante, volvería a llevar con ella.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2026-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'cee17561b54e3cb0f7aecc1d96de7572f3b9f3a175584313525c0b7e6c6e7529'::TEXT, ARRAY[567]::BIGINT[]),
    (532::BIGINT, 'La profe es estricta y tal vez de miedo al inicio, pero al final se vuelve una profe que siempre ayuda, es comprensiva si usted hace las cosas bien, y solo es estricta cuando es necesario. Cae muy bien y la recomiendo 100%.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-06-27T00:00:00+00:00'::TIMESTAMPTZ, '072e1cafe60d5d959eb1feec73b4fdfa2807670b1b36944fef4a1eb65a08a1b0'::TEXT, ARRAY[567]::BIGINT[]),
    (532::BIGINT, 'La profe es seria, pero, muy amable, se preocupa por el estudiante y responde así sea la duda más tonta. Los informes se hacen en clase. Los informes sí los califica estrictamente, pero, los quices son muy fáciles .'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2026-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'f8c85bea313eaca447c1b47a733de4338f9f271dd4995c67e993f40f9bf4b00f'::TEXT, ARRAY[567]::BIGINT[]),
    (532::BIGINT, 'Es muy buena profesora, pero a veces es medio odiosa y califica duro los informes. Las correcciones que hace en los informes te ayudan demasiado para no cometer errores en los demás. Con tal de repasar las prácticas pasas los quices, además que podés pasar el curso con los informes y los parciales.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Tomaría su clase nuevamente']::TEXT[], '2026-05-08T00:00:00+00:00'::TIMESTAMPTZ, 'dd75d3a47847486d6a3916f1c4a41028cf7dcc94610174d6ed76b10361054ac6'::TEXT, ARRAY[567]::BIGINT[]),
    (532::BIGINT, 'Es buena profe, explica todo las veces que haga falta y ayuda bastante con cualquier duda que se tenga, recomendada aunque aveces sea un poco odiosa pero nada fuera de lo normal'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2026-04-04T00:00:00+00:00'::TIMESTAMPTZ, '67b94df92421ad6b08e1ea106fc713d4741fe4fcd7d5af70977b7c17ff405ade'::TEXT, ARRAY[567]::BIGINT[]),
    (532::BIGINT, 'Muy buena profe, explica super claro lo que hay que hacer y brinda ayuda en clase, lo único malo es que los quices son un poco duros, pero con estudiar le va bien.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-12-13T00:00:00+00:00'::TIMESTAMPTZ, '1ed9f351c9049ad9fa0d578c5d12baffbb9db2ec28c1c125cb60f85cb7452403'::TEXT, ARRAY[613]::BIGINT[]),
    (532::BIGINT, 'la profe es muy buena nota, ademas las clases son claras y si uno tiene alguna duda la profesora se la aclara de buena manera, volveria a matricular con ella nuevamente'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-04T00:00:00+00:00'::TIMESTAMPTZ, 'cf4c28d43b25ca5c1967493c9a423a9a3e60ed6c1a050a1953cd2863c81084b9'::TEXT, ARRAY[567]::BIGINT[]),
    (532::BIGINT, 'Una excelente profesora para llevar laboratorio. Es buena gente, pero se mantiene firme a las normas de evaluación. Los quices no son fáciles pero con que usted lea bien la práctica los pasa bien. La recomiendo enteramente.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2025-05-05T00:00:00+00:00'::TIMESTAMPTZ, '9114aafe74f00501368fd21728c12ecfe11a74de098012e4b64aaeec710af7e4'::TEXT, ARRAY[567]::BIGINT[]),
    (532::BIGINT, 'Es muy buena Profe, debe estudiar bastante para los quices que son difíciles y con solo que saque buenas notas de los informes y le ponga en los exámenes pasa. La verdad la recomiendo demasiado'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Aspectos de calificación claros']::TEXT[], '2024-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'ab9eb8d143dd3a3fe7714f731cdc378e89d686aec839599e45acc7b3fb39fd03'::TEXT, ARRAY[613]::BIGINT[]),
    (532::BIGINT, 'Muy linda persona, los quices son fáciles, lo único que califica más duro son los informes pero en realidad se pasa fácil si le pone.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2024-11-27T00:00:00+00:00'::TIMESTAMPTZ, '8bf98da576df6fffd708d86d46446199658ad53f68166be7fba08dbd19112233'::TEXT, ARRAY[613]::BIGINT[]),
    (532::BIGINT, 'Yo detesto química y me gustó el curso'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-08-30T00:00:00+00:00'::TIMESTAMPTZ, '5eef0c0419e5e5bfc00d3ef9191dc74921a9f52d79a9d9a4e30d70b23d3cd8f4'::TEXT, ARRAY[567]::BIGINT[]),
    (532::BIGINT, 'Es buena persona si usted le pone. Los quices son medio complicados al principio pero si usted le agarra el toque entonces no hay problema. Hay que esforzarse en los informes y sí tener todo claro para el examen.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'b5ee4b4b019f593d8b16c475b55f8edffcf0c3bc485dcc16f7da56abaf1c1ffc'::TEXT, ARRAY[567]::BIGINT[]),
    (532::BIGINT, 'Muy buena profesora, es clara y precisa al momento de explicar. Sus quices son muy sencillos, solo es cuestión de estudiar lo asignado y cumplir lo establecido, de ahí puede llevarse bien con ella y el curso se hace demasiado bonito. La recomiendo 100x100.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'f6962b53e7f1f6fbf528b6083944925af429aefa23bf5f9db866d424fe65d6cb'::TEXT, ARRAY[567]::BIGINT[]),
    (532::BIGINT, 'Muy excelente profesora que no le importa tener que explicarte hasta lo más mínimo. Eso sí debe ponerle por que si llega a evaluar duro, pero la verdad gracias a esto si sentí que realmente aprendí en sus clases. Sí hace los reportes, informes y libreta a conciencia creamé que aprenderá y pasará.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2024-06-06T00:00:00+00:00'::TIMESTAMPTZ, '81a322b99f1a9aa1804c18a82c9b0d23a1b7fe50a0d3e0d1e1671bb5cacbe977'::TEXT, ARRAY[567]::BIGINT[]),
    (532::BIGINT, 'Muy excelente profesora, explica muy bien durante las clases, pero debes ser muy preciso en los exámenes e informes ya que califica duro, igual en los quiz.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da crédito extra', 'Aspectos de calificación claros']::TEXT[], '2024-01-23T00:00:00+00:00'::TIMESTAMPTZ, 'b0068de8bf2761a4605dd2fdce8b9ff4d230fd96eaff3754be187927d9f3cf6c'::TEXT, ARRAY[613]::BIGINT[]),
    (532::BIGINT, 'Explica bien, ayuda cuando es requerido, sin embargo la dificultad y la exigencia que pide en los informes y examenes es exagerada, si por horario le queda bien, dele, si no busque una mejor opción'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2024-01-11T00:00:00+00:00'::TIMESTAMPTZ, '04136d872d0a63b32e38229b219b1b3bcf7af9bb2ed8e71318f7a2a9887f07c9'::TEXT, ARRAY[613]::BIGINT[]),
    (532::BIGINT, 'Una profe excelente, califica duro pero está dispuesta a ayudar siempre. Explica con mucha claridad la materia y se ve que le interesa que los estudiantes aprendan. Los quices son duros y los informes los califica duro también.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Inspirador', 'Brinda apoyo']::TEXT[], '2023-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'ef1fa3c54f4d76aff5e37f899ca69f6d0dc495020f07b0db674856fe49b9ba62'::TEXT, ARRAY[613]::BIGINT[]),
    (532::BIGINT, 'Es una buena profesora, en términos generales. Los quices son un toque rudos. Recomendaciones: haga la libreta bien y a tiempo, tenga clara la materia antes de la práctica (repase), haga todas las preguntas que quiera, y preste atención. Es una muy buena opción para matricular'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'ad1f0b3fde00cb0468ca6eeb7ac83cbd526833f92e1360ce6b44bfbe29335295'::TEXT, ARRAY[613]::BIGINT[]),
    (532::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2018-10-02T00:00:00+00:00'::TIMESTAMPTZ, '1b2b7d9e5f8b876877e6c34c38b5c54e489ac28a188cbeb01984cdf5cd832e17'::TEXT, ARRAY[613, 567]::BIGINT[]),
    (532::BIGINT, 'Es súper buena explicando y simpática. Los quizzes no son fáciles pero es muy clara con lo que quiere en los reportes'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-18T00:00:00+00:00'::TIMESTAMPTZ, '9ac687b70475b18a81515bfc0f7a381ae4c43f56a9294ee2ea8dd96eb0fc9f50'::TEXT, ARRAY[567]::BIGINT[]),
    (532::BIGINT, 'Explica bien pero es muy estricta, los quices son MUY difíciles... Y de vez en cuando le gusta ser sarcástica y humillar.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-03T00:00:00+00:00'::TIMESTAMPTZ, 'adc387d72f9a8e9c4908e473392fd82bb5d0350a449a89ba0b661d5daef23e90'::TEXT, ARRAY[613]::BIGINT[]),
    (532::BIGINT, 'Si se hace la libreta a conciencia, se lee el manual de seguridad yse presta atención (se le puede preguntar, sin miedo) ya se tiene el cusro ganado.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2017-07-13T00:00:00+00:00'::TIMESTAMPTZ, '05aedff043d5d276d652443c4ec077a2418d53878e151b5ff387badac89873fb'::TEXT, ARRAY[567]::BIGINT[]),
    (532::BIGINT, 'Muy buena profesora! Le importa que el estudiante realmente aprenda, el curso es duro y a como explica así califica. No duden en matricular con ella! Siempre buscar ayudar al estudiante'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2017-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'f6f3a7729e0ba2afecd5214660d7c9c9bc1f76b574ca1e30878cad205b5d35c9'::TEXT, ARRAY[3181]::BIGINT[]),
    (532::BIGINT, 'Súper recomendada, siempre dispuesta a aclarar dudas, excelente persona.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-28T00:00:00+00:00'::TIMESTAMPTZ, '0e899cdf560d141834d918bb8ef0b0cebb28e8874af087afa876376fb391764e'::TEXT, ARRAY[3181, 3179]::BIGINT[]),
    (532::BIGINT, 'Es una excelente profesora, es simpática, resuelve todas las dudas y busca ayudar al estudiante. Es muy estricta al revisar los informes pero eso le enseña demasiado a uno. Super recomendada.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, '1dc5be1dffd7e220b75673b6dd40eeb8e9ee42521dfb7b2489ec3677459f9b64'::TEXT, ARRAY[567]::BIGINT[]),
    (532::BIGINT, 'ella atiende siempre las dudas, es carismática y es estricta pero porque el curso lo exige, califica duro pero la recomiendo un monton'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'ae890e4090b990b7049b3d063c8abb4baee2d9de0899fad83c0ea8240503ac7a'::TEXT, ARRAY[567]::BIGINT[]),
    (532::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'fe272235adb18f9cd5fa6001d4534e4adfc5399e15910db136ba1918892bc285'::TEXT, ARRAY[567]::BIGINT[]),
    (532::BIGINT, 'Excelente!!!!!!!!!!!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-22T00:00:00+00:00'::TIMESTAMPTZ, '7a0ec2d85389522126e22c0630ba82faca48cb80183bc11d6db85aa5942de81c'::TEXT, ARRAY[567]::BIGINT[]),
    (532::BIGINT, 'Es muy agradable y explica muy bien, califica muy estricto'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-15T00:00:00+00:00'::TIMESTAMPTZ, '63c806670051b9029092b0f268834207bf2d08afc87846ab5b721e9a0774565f'::TEXT, ARRAY[567]::BIGINT[]),
    (532::BIGINT, 'Excelente profesora. No se puede tomar el curso a la ligera si se lleva con ella, califica duro pero por la naturaleza de la materia, esto es algo bueno. En algunas ocasiones no inspira la confianza suficiente para evacuar dudas durante las prácticas, pero de igual forma lo hará. Recomendada.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-05T00:00:00+00:00'::TIMESTAMPTZ, '3dfbf5dac6c0ce79d4e55655863eac89aa9e1dea46cccc6d82421c4ef47314cd'::TEXT, ARRAY[567]::BIGINT[]),
    (532::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Aspectos de calificación claros']::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, '192396a2117f7f7a0c2c754bacabfd6f10fe947232af1bf9837fd6e30591f99c'::TEXT, ARRAY[3181]::BIGINT[]),
    (532::BIGINT, 'Explicaciones claras. La libreta debe estar ordenada, los quices son algo difíciles pero es cuestión de estudiarse bien la materia. Califica justo. Muy buena profe y excelente persona. Recomendada.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-15T00:00:00+00:00'::TIMESTAMPTZ, '883814512cd3c34899330bae801cd05517fc8cab1f6152338361b2d247fd466d'::TEXT, ARRAY[3181]::BIGINT[]),
    (532::BIGINT, 'Es muy buena profe, pero si califica durillo. Y pide de fijo la libreta de lab, sino no puede hacer el lab. Los quices son fáciles, es cuestión de leer el folleto antes y entenderlo bien. Califica duro en los examenes pero recomendadisima. Es muy clara.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Respetado por los estudiantes']::TEXT[], '2016-06-09T00:00:00+00:00'::TIMESTAMPTZ, 'c7fcf9f345deede0566c1cb9a3ab5eace359fae90ecd9f51090e74917819ecb0'::TEXT, ARRAY[567]::BIGINT[]),
    (532::BIGINT, 'Explica muy claro pero califica muy rudo. Si durante su carrera va a necesitar mucho de química, lleve con ella porque lo hace a uno entender de verdad pero por más que uno maneje la materia igual va atener un promedio medio bajo porque si califica muy rudo'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-08T00:00:00+00:00'::TIMESTAMPTZ, '503e0f249510856ccfe2d89fd19ba9d5d3c54d31e24bf225a2c0156c672d344e'::TEXT, ARRAY[567]::BIGINT[]),
    (532::BIGINT, 'Una excelente profesora, si puede meter el curso con ella hagalo :)'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-02-05T00:00:00+00:00'::TIMESTAMPTZ, '656935b2e3aeae30dfd7807804636641468ec3f01cd723a63615db0c602285c1'::TEXT, ARRAY[613]::BIGINT[]),
    (532::BIGINT, 'Una gran profesora y persona. Le interesa que usted aprenda, que entienda. Califica justo y hace quices muy fáciles.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-25T00:00:00+00:00'::TIMESTAMPTZ, '8c1a37fd5b7b2d6ca911167c31193b5481cd20e9ecf3ba48a425eae1bd0d3009'::TEXT, ARRAY[613]::BIGINT[]),
    (532::BIGINT, 'Es un amor! Califica algo rudo si ud no hace las cosas como ella los explico (lo cual hace muy claro) Muy atenta a la hora de explicar y de la consulta 100% recomendada para cualquier curso!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-19T00:00:00+00:00'::TIMESTAMPTZ, '8736f119d6a5150dad0861042c644bd877648b14b201b0edda4369b3ae7f99d0'::TEXT, ARRAY[613]::BIGINT[]),
    (532::BIGINT, 'Explica muy bien antes de realizar cada practica, explica la materia hasta entender lo cual ayuda mucho al hacer los informes quices fáciles si estudia, califica algo duro, muy tolerable'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'd19f88170bf761b769e33a8a17cbf97ca296df5dad91e3be229f0d9229bbcfed'::TEXT, ARRAY[567]::BIGINT[]),
    (532::BIGINT, 'Muy buena opcion para lab, siempre explica muy buen la teoria antes de empezar lo que ayuda a aprender y hacer el informe. Lo ayuda a uno con dudas durante la practica'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-20T00:00:00+00:00'::TIMESTAMPTZ, '2c1b31360d1b5d83e07937f07601252b669b6daf91639cdeb1121042c37941e1'::TEXT, ARRAY[613]::BIGINT[]),
    (532::BIGINT, 'La profe es excelente persona,explica muy bien y se preocupa por que los estudiantes aprendan.Es estricta pero lo necesario para que el estudiante se preocupe por el curso y aprenda del mismo cosa que con ella va a lograr.Lleve al día la materia para los quices que son algo difíciles y pasa bien.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-19T00:00:00+00:00'::TIMESTAMPTZ, '41266256a52f042d09d83fcfa389df94f7a4ce3af5dc0ebbad40da8fd35021a4'::TEXT, ARRAY[3181]::BIGINT[]),
    (532::BIGINT, 'Muy agradable, sabe mucho. Califica como debe ser. Explica muy claro y ayuda bastante cuando se le pide. Tiene en cuenta que se esta empezando y no es exigente por eso. Recomendada para los primeros ingresos.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'd7006c0ee48e999da36520fd540d4a953006b82402ee0210a281d92607aff1c8'::TEXT, ARRAY[567]::BIGINT[]),
    (532::BIGINT, 'Ayuda bastsante, explica bien lo que se tiene que hacer y sino se entiende le explica a uno de nuevo. Es cierto, puede ser algo odiosa pero buena profesora al final de cuentas.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-03T00:00:00+00:00'::TIMESTAMPTZ, 'eee32b9fd70f3703c844f6843d6b47a76b1422385e22fb2baab269f3587eb34b'::TEXT, ARRAY[567]::BIGINT[]),
    (532::BIGINT, 'La mejor para laboratorios de química basica. muy buena explicando, puede responder algo odiosa a las dudas pero cuando se muestra interés por la clase le responde hasta que usted entienda'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '571c7c0f978432307768188b7a16a90d5ebf08caec5cafb2e8236432a3b810e9'::TEXT, ARRAY[567, 613]::BIGINT[]),
    (532::BIGINT, '100% Recomendada, muy buena, excelente persona'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-14T00:00:00+00:00'::TIMESTAMPTZ, '3381bb57bb65869ca5228bf761d7a638c3ac89d1bc00e725ca32bf26d5afd6fb'::TEXT, ARRAY[613]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
